       (io_o_out[3]));
  xilinx_not_3 ro_invs_not_gate_3(.io_i0 (io_o_out[3]), .io_out
       (io_o_out[4]));
  xilinx_not_4 ro_invs_not_gate_4(.io_i0 (io_o_out[4]), .io_out
       (io_o_out[5]));
  xilinx_not_5 ro_invs_not_gate_5(.io_i0 (io_o_out[5]), .io_out
       (io_o_out[6]));
  xilinx_nand ro_nand_nand_gate_0(.io_i0 (io_i_en), .io_i1
       (io_o_out[6]), .io_out (io_o_out[0]));
endmodule

